<script setup lang="ts">
import {ref,onUnmounted} from 'vue'
import PublicContentOperator from './PublicContentOperator.vue'
import type {State} from '../domain/types'
import {installPublicResources,type PublicPackage} from '../domain/resources'
import {fetchPublicResources} from '../platform/resources'
const props=defineProps<{state:State;canInstallCards:boolean;canInstallScenes:boolean;persist:(state:State)=>boolean}>()
const pack=ref<PublicPackage|null>(null),cards=ref<string[]>([]),scenes=ref<string[]>([]),busy=ref(false),error=ref(''),message=ref(''),revision=ref(0)
const operatorOpen=ref(false)
let disposed=false;onUnmounted(()=>disposed=true)
async function load(){busy.value=true;error.value='';message.value='';pack.value=null;cards.value=[];scenes.value=[];try{const result=await fetchPublicResources();if(disposed)return;pack.value=result.package;revision.value=result.revision;if(!result.package)message.value='暂时没有已发布的公共资源。'}catch(e){if(!disposed)error.value=e instanceof Error?e.message:'获取失败'}finally{if(!disposed)busy.value=false}}
function toggle(list:string[],id:string,allowed:boolean){if(!allowed)return;const i=list.indexOf(id);if(i<0)list.push(id);else list.splice(i,1)}
function install(){if(!pack.value)return;error.value='';message.value='';try{if(cards.value.length&&!props.canInstallCards||scenes.value.length&&!props.canInstallScenes)throw new Error('当前家庭权限不允许安装所选卡片或场景');const next=installPublicResources(props.state,pack.value,{cards:cards.value,scenes:scenes.value},revision.value);if(props.persist(next)){message.value=`已安装 ${cards.value.length} 张卡片与 ${scenes.value.length} 个场景。`;cards.value=[];scenes.value=[]}else error.value='本机保存失败，资源尚未安装。'}catch(e){error.value=e instanceof Error?e.message:'安装失败'}}
</script>
<template><view class="public-resources"><text class="section-title">公共资源</text><text class="modal-copy">手动获取资源后，逐项选择安装。已有同名资料或相同资源会保留；冲突时取消该项即可继续。有关联的卡片和场景需要同时选择。</text><button role="button" tabindex="0" class="outline-button" :disabled="busy" @click="load">{{busy?'正在获取…':'获取公共资源预览'}}</button><view v-if="pack" class="resource-preview"><text class="section-title">{{pack.title}}</text><text>版本 {{pack.id}} · 发布 {{revision}}</text><text>来源：{{pack.source}}</text><text>许可：{{pack.license}}</text><text class="modal-copy">请选择同意按上述许可使用的项目：</text><button role="button" tabindex="0" v-for="card in pack.cards" :key="card.id" :aria-pressed="cards.includes(card.id)" :disabled="!canInstallCards" @click="toggle(cards,card.id,canInstallCards)">{{cards.includes(card.id)?'✓ ':''}}卡片：{{card.label}} — {{card.description}}</button><button role="button" tabindex="0" v-for="scene in pack.scenes" :key="scene.id" :aria-pressed="scenes.includes(scene.id)" :disabled="!canInstallScenes" @click="toggle(scenes,scene.id,canInstallScenes)">{{scenes.includes(scene.id)?'✓ ':''}}场景：{{scene.name}} — {{scene.description}}</button><button role="button" tabindex="0" class="primary-button" :disabled="!cards.length&&!scenes.length||!!cards.length&&!canInstallCards||!!scenes.length&&!canInstallScenes" @click="install">安装所选资源到本机</button></view><button role="button" tabindex="0" class="outline-button" @click="operatorOpen=!operatorOpen">公共内容运营入口</button><PublicContentOperator v-if="operatorOpen" @close="operatorOpen=false"/><text v-if="error" role="alert" class="error-copy">{{error}}</text><text v-if="message" role="status">{{message}}</text></view></template>
<style scoped>.public-resources,.resource-preview{display:flex;flex-direction:column;gap:16px;min-width:0}.resource-preview button{white-space:normal;text-align:left;font-size:16px;padding:12px}.resource-preview button[aria-pressed=true]{outline:2px solid #327e67}</style>
